<div class="grid gap-5 md:grid-cols-2"><x-ui.input name="organization_name" label="Organisation" :value="$item->organization_name" required/><x-ui.select name="framework" label="Référentiel" :value="$item->framework" :options="array_combine(['ISO 14001','ISO 50001','GRS','OEKO-TEX','Internal'],['ISO 14001','ISO 50001','GRS','OEKO-TEX','Référentiel interne'])" required/><x-ui.select name="status" label="Statut" :value="$item->status ?: 'draft'" :options="['draft'=>'Brouillon','in_progress'=>'En cours','ready'=>'Prêt','needs_action'=>'Actions requises']" required/><x-ui.input name="readiness_score" label="Score de préparation" type="number" :value="$item->readiness_score" min="0" max="100"/><x-ui.input name="assessment_date" label="Date d’évaluation" type="date" :value="optional($item->assessment_date)->format('Y-m-d')" required/><x-ui.input name="next_review_date" label="Prochaine revue" type="date" :value="optional($item->next_review_date)->format('Y-m-d')"/><div class="md:col-span-2"><x-ui.textarea name="notes" label="Constats et actions" :value="$item->notes" rows="6"/></div></div>
